import http from 'http';
import net from 'net';

const rawRequest = port =>
  new Promise(resolve => {
    const raw = net.connect(port, '127.0.0.1', () => {
      raw.write('GET /hal/ws?sessionId=known HTTP/1.1\r\nHost: 127.0.0.1\r\nUpgrade: websocket\r\nConnection: Upgrade\r\nSec-WebSocket-Key: dGhlIHNhbXBsZSBub25jZQ==\r\nSec-WebSocket-Version: 13\r\n\r\n');
    });
    let data = '';
    raw.on('data', c => (data += c.toString()));
    raw.on('close', () => resolve(data.split('\r\n').slice(0, 8).join(' | ')));
    raw.on('error', e => resolve('ERR ' + e.code));
    setTimeout(() => resolve('TIMEOUT: ' + data.slice(0, 80)), 1500);
  });

const serve = makeServer =>
  new Promise(resolve => {
    const server = makeServer();
    server.listen(0, '127.0.0.1', () => resolve(server));
  });

const run = async (label, makeServer) => {
  const server = await serve(makeServer);
  const answer = await rawRequest(server.address().port);
  server.close();
  console.log(JSON.stringify({label, answer}));
};

await run('no-request-listener', () => http.createServer());
await run('undefined-returning-listener', () => http.createServer(() => undefined));
await run('with-upgrade-listener', () => {
  const s = http.createServer(() => undefined);
  s.on('upgrade', (_req, socket) => {
    socket.write('HTTP/1.1 101 Switching Protocols\r\nUpgrade: websocket\r\nConnection: Upgrade\r\nSec-WebSocket-Accept: s3pPLMBiTxaQ9kYGzzhZRbK+xOo=\r\n\r\n');
    socket.end();
  });
  return s;
});
process.exit(0);
